def max_value_on_paths(N, grid_values):
    # Initialize a 2D array to store the maximum values for each position
    dp = [[0] * N for _ in range(N)]

    # Loop through the grid_values and update the dp array
    for x, y, value in grid_values:
        dp[x][y] = value

    # Loop through the array and calculate the maximum value for each position
    for x in range(N):
        for y in range(N):
            if x > 0 and y > 0:
                dp[x][y] += max(dp[x - 1][y], dp[x][y - 1])

    # Return the maximum value for the bottom-right corner of the array
    return dp[N - 1][N - 1]

