def cantor_numbering(N: int) -> str:
    """
    Generates the numerator and denominator of the N-th term in the Cantor table.

    :param N: The position in the Cantor table to find the corresponding fraction for.
    :return: A string representation of the fraction at the N-th position in the Cantor table.
    """
    if N < 1:
        raise ValueError("N must be a positive integer greater than or equal to 1.")
    if N == 1:
        return "1/1"
    else:
        n_str = str(N)
        rev_n_str = n_str[::-1]
        num = 0
        sum_len = 0
        count = 0
        for i in range(len(n_str)):
            if int(rev_n_str[i]) % 2 == 0:
                count += 1
        for i in range(len(n_str)):
            if sum_len < count:
                num += int(n_str[i]) * 10 ** i
            else:
                num += (int(n_str[i]) + 1) * 10 ** i
            if int(n_str[i]) % 2 == 0:
                sum_len += 1
        den = int(n_str)
        return f"{num}/{den}"

