def max_product(num_str, N, K):
    if N == 1 or K == 0:
        return int(num_str)

    # Split the number string into two parts
    left = num_str[:N // 2]
    right = num_str[N // 2:]

    # Recursively find the maximum product for each part
    left_product = max_product(left, N // 2, K - 1)
    right_product = max_product(right, N // 2, K - 1)

    # Find the maximum product of the current part
    current_product = left_product * right_product

    # Return the maximum of the current product and the product of the two parts
    return max(current_product, left_product + right_product)

